class Event(object):
    """
    A class representing one of the valid EVENTs that Tor
    supports.

    This allows you to listen for such an event; see
    TorController.add_event The callbacks will be called every time
    the event in question is received.
    """
    def __init__(self, name):
        self.name = name
        self.callbacks = []

    def listen(self, cb):
        self.callbacks.append(cb)

    def unlisten(self, cb):
        self.callbacks.remove(cb)

    def got_update(self, data):
        for cb in self.callbacks:
            try:
                cb(data)
            except Exception:
                # Log the exception but continue processing other callbacks
                log.err(
                    failure.Failure(),
                    "Error in event listener callback for event '%s'" % self.name
                )


def unquote(word):
    if len(word) == 0:
        return word

